/* Data access layer. Everything is static JSON generated by tools/build.py, so
   the core bundle is fetched once and cached in memory; per-match detail is
   fetched on demand. */

const DATA = 'data/';
const cache = new Map();

async function getJSON(path) {
  if (cache.has(path)) return cache.get(path);
  const p = fetch(DATA + path, { cache: 'no-cache' }).then(r => {
    if (!r.ok) throw new Error(`${path}: ${r.status}`);
    return r.json();
  });
  cache.set(path, p);
  return p;
}

export const store = {
  meta: null,
  teams: [],
  players: [],
  standings: {},
  matches: [],
  analytics: null,
  teamById: new Map(),
  playerById: new Map(),
  matchByKey: new Map(),
  scopes: [],

  async load() {
    const [meta, teams, players, standings, matches, analytics] = await Promise.all([
      getJSON('meta.json'), getJSON('teams.json'), getJSON('players.json'),
      getJSON('standings.json'), getJSON('matches.json'), getJSON('analytics.json'),
    ]);
    this.meta = meta;
    this.teams = teams;
    this.players = players;
    this.standings = standings;
    this.matches = matches;
    this.analytics = analytics;
    this.teamById = new Map(teams.map(t => [t.id, t]));
    this.playerById = new Map(players.map(p => [p.id, p]));
    this.matchByKey = new Map(matches.map(m => [m.key, m]));
    this.scopes = meta.stages.map(s => ({
      key: s.key, label: s.label, title: s.title, matches: s.matches,
    }));
    return this;
  },

  match(key) { return getJSON(`match/${key}.json`); },

  stageLabel(key) {
    const s = this.scopes.find(x => x.key === key);
    return s ? s.label : key;
  },

  team(id) { return this.teamById.get(id); },
  player(id) { return this.playerById.get(id); },

  /* Teams / players that actually appear in a scope, with the scope's stat block
     flattened onto `s` for easy sorting. */
  teamsIn(scope) {
    return this.teams.filter(t => t.stages[scope]).map(t => ({ ...t, s: t.stages[scope] }));
  },
  playersIn(scope) {
    return this.players.filter(p => p.stages[scope]).map(p => ({ ...p, s: p.stages[scope] }));
  },
  matchesIn(scope) {
    return this.matches.filter(m => m.stage === scope);
  },
  rosterOf(teamId, scope) {
    return this.playersIn(scope)
      .filter(p => p.teamId === teamId)
      .sort((a, b) => b.s.kills - a.s.kills);
  },
  standingsIn(scope) { return this.standings[scope] || []; },

  /* Per-match rows for one team or player, in tournament order. */
  teamMatchRows(teamId, scope) {
    const rows = [];
    for (const m of this.matchesIn(scope)) {
      const t = (m.teams || []).find(x => x.id === teamId);
      rows.push({ match: m, team: t });
    }
    return rows;
  },
};

export const scopeState = {
  key: localStorage.getItem('pmgo.scope') || '',
  set(k) {
    this.key = k;
    try { localStorage.setItem('pmgo.scope', k); } catch { /* private mode */ }
  },
  /* Falls back to the most recent stage (the last one in the tournament). */
  valid(scopes) {
    if (!scopes.some(s => s.key === this.key)) this.key = scopes[scopes.length - 1]?.key || '';
    return this.key;
  },
};
